delete from _tpl_target t where not public._perm_valid(t.s, t.a, 'branch');
delete from public.perm_role_grants g using public.perm_roles r
 where g.role_id = r.id and r.org_id is null and r.key in (select distinct k from _tpl_target)
   and not exists (select 1 from _tpl_target t where t.k = r.key and t.s = g.section and t.a = g.action);
insert into public.perm_role_grants(role_id, section, action, scope)
select r.id, t.s, t.a, 'branch' from _tpl_target t join public.perm_roles r on r.key = t.k and r.org_id is null
on conflict do nothing;